// Prépare chaque email reçu (IMAP, OVH) : expéditeur, objet, texte (sans l'historique cité), liens.
const out = [];
for (const item of $input.all()) {
  const e = item.json;
  const from = e.from?.value?.[0] ?? {};
  const to = e.to?.value?.[0]?.address ?? null;
  const html = e.html || '';
  let text = e.text || html.replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
  text = text.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim();

  // on coupe l'historique cité (« Le … a écrit : », « On … wrote: », « De : … »)
  const cut = text.search(/\n\s*(Le .{5,120}a écrit\s*:|On .{5,120}wrote:|-{2,}\s*Original Message|-{2,}\s*Message d'origine|De\s*:.*\n\s*(Envoyé|Date)\s*:)/i);
  const reply = (cut > 20 ? text.slice(0, cut) : text).trim();

  // liens de l'email (utile pour retrouver la conversation sur Codeur, Fiverr, Malt…)
  const links = [...new Set([...html.matchAll(/href=["'](https?:\/\/[^"'\s>]+)["']/gi)].map((m) => m[1]))]
    .filter((u) => !/unsubscribe|desinscri|désinscri|optout|tracking-pixel|\.(png|jpe?g|gif)(\?|$)/i.test(u))
    .slice(0, 15);

  // indices anti-arnaque calculés avant l'IA
  const fromDomain = (from.address || '').split('@')[1]?.toLowerCase() || '';
  const PLATFORM_DOMAINS = { fiverr: ['fiverr.com'], codeur: ['codeur.com'], malt: ['malt.com', 'malt.fr'], comeup: ['comeup.com'], upwork: ['upwork.com'] };
  const allText = `${e.subject || ''} ${reply}`.toLowerCase();
  const alerts = [];
  for (const [name, domains] of Object.entries(PLATFORM_DOMAINS)) {
    const official = domains.some((d) => fromDomain === d || fromDomain.endsWith('.' + d));
    if (allText.includes(name) && !official && /(compte|account|suspend|verify|v[ée]rifi|password|mot de passe|payment|paiement|security|s[ée]curit|login|connexion)/i.test(allText)) {
      alerts.push(`parle de ${name} mais n'est PAS envoyé par ${domains[0]} (imitation probable)`);
    }
  }
  if (/whats\s?app|telegram|signal app|skype|wechat|discord|hangouts|\+\d{9,}/i.test(allText)) alerts.push('demande de passer sur WhatsApp / Telegram / autre messagerie');
  if (/crypto|bitcoin|usdt|\bbtc\b|wallet|western union|gift ?card|carte cadeau/i.test(allText)) alerts.push('paiement crypto / carte cadeau');
  if (/docs\.google|drive\.google|bit\.ly|tinyurl|wetransfer|\.zip\b|\.exe\b|\.apk\b/i.test(reply + ' ' + links.join(' '))) alerts.push('lien ou fichier externe à ouvrir');
  if (/(buy|rent|achet|lou)\w*.{0,30}(your|votre|ton).{0,20}(account|compte|gig|profil)/i.test(allText)) alerts.push('veut acheter / louer le compte');
  if (/(i can|i will|je peux|je vais).{0,40}(rank|boost|reviews?|avis|traffic|seo|promote|promouvoir)/i.test(allText)) alerts.push('vend des avis / du référencement / de la promotion');

  // conversation : le tout premier message de la discussion (références de l'email)
  const refs = Array.isArray(e.references) ? e.references : String(e.references || '').split(/\s+/).filter(Boolean);
  const email = {
    external_id: e.messageId || e.id,
    thread_id: refs[0] || e.inReplyTo || e.messageId || e.threadId || null,
    from_email: (from.address || '').toLowerCase(),
    from_name: from.name || null,
    to_email: to,
    subject: e.subject || '',
    body: reply.slice(0, 20000),
    received_at: e.date || new Date().toISOString(),
  };

  const prompt = `Trie cet email reçu sur l'adresse pro.

RÈGLES
- "client" : une vraie personne ou entreprise qui écrit directement : réponse à un email de prospection, demande de devis, question, client existant.
- "plateforme" : notification d'une plateforme de freelance (Codeur, Fiverr, Malt, ComeUp, 5euros, Upwork, LinkedIn…) qui annonce un NOUVEAU projet, une demande ou un message d'un client. Récupère le nom du client, le projet, le budget et le lien vers la conversation ou le projet (platform_url : le lien du bouton « Voir le message », « Répondre » ou « Voir le projet », choisi dans la liste de liens). Une notification de plateforme sans client (newsletter, paiement reçu, facture, conseil) = "autre".
- "autre" : newsletters, factures, banque, réseaux sociaux, Google, confirmations, notifications automatiques. Les notifications du formulaire du site solvelab.fr et de Cal.com sont DÉJÀ dans le CRM : "autre".
- verdict "spam" : démarchage de masse (SEO, backlinks, nom de domaine, crypto, « dear sir »), phishing, arnaque, robot. verdict "a_verifier" si tu hésites entre vraie demande et spam. Sinon "ok".

ARNAQUES FRÉQUENTES SUR FIVERR ET LES PLATEFORMES (verdict "spam") :
- demande de continuer sur WhatsApp, Telegram, Skype, Discord, par email ou par téléphone (interdit par Fiverr, presque toujours une arnaque) ;
- paiement en crypto, carte cadeau, virement hors plateforme, chèque à encaisser ;
- lien Google Docs / Drive / fichier à télécharger « avec le cahier des charges » avant toute discussion ;
- quelqu'un qui VEND quelque chose à Nolla : avis 5 étoiles, promotion du profil, SEO, trafic, « je peux faire tes commandes », achat ou location du compte ;
- faux email « Fiverr » ou « Codeur » qui ne vient pas du vrai site (compte suspendu, vérifiez votre identité, paiement bloqué) = phishing ;
- message vague et copié-collé (« Hello dear, I have a project for you, are you available? ») sans aucun détail sur le projet.
UNE VRAIE DEMANDE ("ok") : décrit un projet précis lié aux services de SolveLab (site internet, automatisation / IA, outil sur mesure, pub vidéo), pose des questions sur le prix, le délai ou le contenu, et reste sur la plateforme. Un vrai message de Fiverr vient de @fiverr.com.
Si le message est trop court pour juger (la notification ne montre qu'un extrait) : "a_verifier".
Les indices calculés automatiquement comptent beaucoup : un seul indice grave (imitation, crypto, WhatsApp/Telegram) suffit pour "spam".
- classement (seulement si category = "client", sinon null) : "chaud" (intéressé, veut un devis, un RDV, pose des questions, nouvelle demande), "a_relancer" (pas maintenant, plus tard : mets relance_le), "pas_interesse", "stop" (demande de ne plus être contacté ou de se désinscrire).
- N'invente rien : null si l'info n'est pas dans l'email.

Réponds UNIQUEMENT avec ce JSON :
{"category":"client|plateforme|autre","verdict":"ok|a_verifier|spam","source":"email|codeur|fiverr|malt|comeup|5euros|upwork|linkedin|autre_plateforme","classement":"chaud|a_relancer|pas_interesse|stop|null","relance_le":"AAAA-MM-JJ ou null","resume":"une phrase courte en français","platform_url":"lien ou null","lead":{"company_name":null,"contact_name":null,"email":null,"phone":null,"city":null,"interest":null,"budget":null}}

INDICES CALCULÉS AUTOMATIQUEMENT : ${alerts.length ? alerts.join(' ; ') : 'aucun'}

EMAIL
De : ${email.from_name || ''} <${email.from_email}>
Objet : ${email.subject}
Texte :
${reply.slice(0, 6000)}

Liens trouvés :
${links.join('\n') || '(aucun)'}`;

  const system = "Tu tries la boîte mail pro de SolveLab, agence digitale à Caen (sites internet, automatisation et IA, outils sur mesure, pub vidéo). Tu réponds uniquement avec un objet JSON valide, sans aucun texte autour.";
  out.push({ json: {
    email,
    // Gemini (gratuit) — utilisé par défaut
    gemini_body: {
      systemInstruction: { parts: [{ text: system }] },
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { responseMimeType: 'application/json', maxOutputTokens: 800, temperature: 0 },
    },
    // Claude (payant, ~1 €/mois) — pour passer à Claude plus tard, voir docs/MISE-EN-ROUTE.md
    anthropic_body: {
      model: 'claude-haiku-5-5',
      max_tokens: 700,
      system: "Tu tries la boîte mail pro de SolveLab, agence digitale à Caen (sites internet, automatisation et IA, outils sur mesure, pub vidéo). Tu réponds uniquement avec un objet JSON valide, sans aucun texte autour.",
      messages: [{ role: 'user', content: prompt }],
    },
  }, pairedItem: item.pairedItem ?? { item: out.length } });
}
return out;

// Lit la réponse de l'IA et prépare l'envoi au CRM.
const prepared = $('Préparer l\'email').all();
return $input.all().map((item, i) => {
  const email = prepared[i]?.json.email ?? {};
  let ai = null;
  try {
    // réponse de Gemini (candidates) ou de Claude (content)
    const parts = item.json.candidates?.[0]?.content?.parts ?? item.json.content ?? [];
    const raw = parts.map((c) => c.text ?? '').join('').trim();
    const json = raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
    ai = JSON.parse(json);
  } catch (e) { ai = null; }

  const nul = (v) => (v === 'null' || v === '' || v === undefined ? null : v);
  if (!ai) {
    return { json: { ...email, category: 'client', verdict: 'a_verifier', source: 'email', ai_summary: "L'IA n'a pas pu trier cet email : à vérifier." } };
  }
  const lead = Object.fromEntries(Object.entries(ai.lead ?? {}).map(([k, v]) => [k, nul(v)]));
  return { json: {
    ...email,
    category: ai.category,
    verdict: ai.verdict,
    source: ai.category === 'plateforme' ? (nul(ai.source) ?? 'plateforme') : 'email',
    classement: nul(ai.classement),
    relance_le: nul(ai.relance_le),
    ai_summary: nul(ai.resume),
    platform_url: nul(ai.platform_url),
    lead,
  } };
});
